# Builds the heap carry worker at O0 and O2 into build/m4-crt-heap-carry-<level>.
# Same compiler, flags and guest objects as the parser carry (build/m4-crt-parser-carry-<level>),
# plus the already-lifted heap-init and mode-1 allocator objects. No worker is executed.
param([string[]]$Levels=@('O0','O2'))
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$vs='C:/Program Files/Microsoft Visual Studio/18/Community'
$llvm=Join-Path $root 'local/tools/llvm-21.1.8/clang+llvm-21.1.8-x86_64-pc-windows-msvc/bin'
$cmake=Join-Path $vs 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe'
$ninja=Join-Path $vs 'Common7/IDE/CommonExtensions/Microsoft/CMake/Ninja/ninja.exe'
Import-Module (Join-Path $vs 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll')
Enter-VsDevShell -VsInstallPath $vs -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64'|Out-Null
foreach($level in $Levels){
 $cache=Get-Content (Join-Path $root "build/m4-crt-parser-carry-$level/CMakeCache.txt")
 $defs=@()
 foreach($line in $cache){if($line -match '^(MW34_[A-Z_]+):[A-Z]+=(.*)$' -and $Matches[1] -notin @('MW34_COMPOSITION_SOURCE','MW34_COMPOSITION_DIRECTORY')){$defs+="-D$($Matches[1])=$($Matches[2])"}}
 $heap=@(
  "reports/m4-crt-attach/lifts-r16/attach-$level.obj","reports/m4-crt-attach/lifts-r16/mtinit-$level.obj","reports/m4-crt-attach/lifts-r16/mtinitlocks-$level.obj","reports/m4-crt-attach/lifts-r16/calloc-$level.obj","reports/m4-crt-attach/lifts-r16/initptd-$level.obj","reports/m4-crt-attach/lifts-r16/attach2-$level.obj","reports/m4-crt-attach/lifts-r16/ioinit-$level.obj","reports/m4-crt-attach/lifts-r16/ioinit_cold-$level.obj","reports/m4-crt-attach/lifts-r16/ioinit_tail_cac-$level.obj","reports/m4-crt-attach/lifts-r16/ioinit_tail_cb0-$level.obj","reports/m4-crt-attach/lifts-r16/attach3-$level.obj","reports/m4-crt-attach/lifts-r16/envstrings-$level.obj","reports/m4-crt-attach/lifts-r16/attachb1-$level.obj","reports/m4-crt-attach/lifts-r16/wcmdln-$level.obj","reports/m4-crt-attach/lifts-r16/attachb2-$level.obj","reports/m4-crt-attach/lifts-r16/initmbctable-$level.obj","reports/m4-crt-attach/lifts-r16/setmbcp-$level.obj","reports/m4-crt-attach/lifts-r16/getsyscp-$level.obj","reports/m4-crt-attach/lifts-r16/setsbuplow-$level.obj","reports/m4-crt-attach/lifts-r16/lcmapa-$level.obj","reports/m4-crt-attach/lifts-r16/gettypea-$level.obj","reports/m4-crt-attach/lifts-r16/lock-$level.obj","reports/m4-crt-attach/lifts-r16/lock_tail-$level.obj","reports/m4-crt-attach/lifts-r16/lock_enter-$level.obj","reports/m4-crt-attach/lifts-r16/unlock-$level.obj","reports/m4-crt-attach/lifts-r16/memset-$level.obj","reports/m4-crt-attach/lifts-r16/strncnt-$level.obj","reports/m4-crt-attach/lifts-r16/attachb3-$level.obj","reports/m4-crt-attach/lifts-r16/setenvp-$level.obj","reports/m4-crt-attach/lifts-r16/strlen-$level.obj","reports/m4-crt-attach/lifts-r16/strcpy-$level.obj","reports/m4-crt-attach/lifts-r16/attachb4-$level.obj","reports/m4-crt-attach/lifts-r16/attach_epilogue-$level.obj","reports/m4-crt-attach/lifts-r16/cinit-$level.obj","reports/m4-crt-attach/lifts-r16/initterm-$level.obj","reports/m4-crt-attach/lifts-r16/initstdio-$level.obj","reports/m4-crt-attach/lifts-r16/initstdio_cold-